'use client';
import {useState,useEffect,useRef} from 'react';
import {LayoutDashboard,Users,BookOpen,CalendarDays,ClipboardCheck,ArrowUpRight,ArrowRight,ChevronRight,ChevronLeft,Plus,Search,Check,Lock,Clock,FileText,Download,ExternalLink,Mic,Send,Sparkles,GraduationCap,Layers,Globe,Briefcase,Mail,BarChart3,Puzzle,Lightbulb,Award,Contact,MoreHorizontal,ArrowUp,ArrowDown,X,RotateCcw,Play,CheckCircle2,ShieldCheck,Headphones,MessageSquare,Settings,LogOut,Square} from 'lucide-react';
import {modules,students,initialState,sections,statusLabels,rubricLabels} from '../../lib/data';
const KEY='tuinterin-demo-state-v1';
const icons={contact:Contact,briefcase:Briefcase,mail:Mail,users:Users,chart:BarChart3,puzzle:Puzzle,bulb:Lightbulb,award:Award};
const mod=id=>modules.find(m=>m.id===id);
const words=t=>t.trim()?t.trim().split(/\s+/).length:0;
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('es-AR',{day:'numeric',month:'short'});
const Button=({children,onClick,kind='',className='',...rest})=><button className={`btn ${kind} ${className}`} onClick={onClick} {...rest}>{children}</button>;
const Badge=({children,tone=''})=><span className={`badge ${tone}`}>{children}</span>;
const Avatar=({id='lucia',size=''})=><span className={`avatar ${id} ${size}`}>{id==='tutor'?'RH':students[id].initials}</span>;
const Icon=({module})=>{const C=icons[module.icon]||BookOpen;return <span className={`module-icon ${module.id}`}><C size={23}/></span>;};
const Empty=({title,children,action})=><div className="empty"><span className="empty-icon"><Layers size={28}/></span><h2>{title}</h2><p>{children}</p>{action}</div>;

export default function Academy(){
 const [auth,setAuth]=useState(null),[code,setCode]=useState(''),[authError,setAuthError]=useState(''),[authBusy,setAuthBusy]=useState(false);
 const [state,setState]=useState(null),[role,setRole]=useState('tutor'),[view,setView]=useState('dashboard'),[student,setStudent]=useState('lucia'),[moduleId,setModuleId]=useState('M01'),[toast,setToast]=useState(''),[dialog,setDialog]=useState(null),[budget,setBudget]=useState(null),[guide,setGuide]=useState(false);
 const notify=t=>{setToast(t);setTimeout(()=>setToast(''),3800);};
 async function unlock(payload){setAuthBusy(true);setAuthError('');try{const r=await fetch('/api/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error);localStorage.setItem('tuinterin-demo-access',d.token);setAuth(true);}catch(e){setAuthError(e.message);setAuth(false);}finally{setAuthBusy(false);}}
 useEffect(()=>{fetch('/api/access').then(r=>r.json()).then(d=>{if(d.authorized)setAuth(true);else{const token=localStorage.getItem('tuinterin-demo-access');if(token)unlock({token});else setAuth(false);}}).catch(()=>setAuth(false));},[]);
 useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem(KEY));setState(saved?.version===1?saved:initialState());}catch{setState(initialState());}},[]);
 useEffect(()=>{if(state)localStorage.setItem(KEY,JSON.stringify(state));},[state]);
 async function refreshBudget(){try{const r=await fetch('/api/budget');if(r.ok)setBudget(await r.json());}catch{}}
 useEffect(()=>{if(auth)refreshBudget();},[auth]);
 const update=fn=>setState(s=>{const n=structuredClone(s);fn(n);return n;});
 const go=(v,id)=>{if(id&&students[id])setStudent(id);if(id&&mod(id))setModuleId(id);setView(v);window.scrollTo({top:0,behavior:'smooth'});};
 const switchRole=r=>{setRole(r);if(r!=='tutor')setStudent(r);go('dashboard');};
 const currentStudent=role==='tutor'?student:role;
 const plan=state?.plans[currentStudent];
 const item=plan?.items.find(x=>x.id===moduleId);
 const openModule=id=>{if(role!=='tutor'&&state.plans[role]?.items.find(i=>i.id===id)?.status==='locked'){notify('Tu profesora liberará este material cuando corresponda.');return;}go('module',id);};
 if(auth===null||!state)return <div className="loading"><span className="logo">tuinterin<span>.</span></span><p>Preparando tu academia…</p></div>;
 if(!auth)return <div className="access-page"><div className="access-brand"><span className="logo">tuinterin<span>.</span></span><Badge>ACADEMY · PRODUCT DEMO</Badge></div><div className="access-layout"><div className="access-copy"><span className="eyebrow">UNA BIBLIOTECA. MUCHOS CAMINOS.</span><h1>El inglés que te lleva<br/><em>más lejos.</em></h1><p>Una experiencia conectada para quienes aprenden y quienes los acompañan.</p><img src="/api/access-art" alt="" onError={e=>{e.currentTarget.style.display='none';}}/><div className="access-footer">Presentación de producto · 12 de octubre de 2026</div></div><form className="access-card" onSubmit={e=>{e.preventDefault();unlock({code});}}><span className="access-lock"><Lock size={25}/></span><h2>Un vistazo al futuro.</h2><p>Introduce el código de invitación para explorar la demo de Tuinterin Academy.</p><label>Código de acceso<input autoFocus inputMode="numeric" autoComplete="one-time-code" maxLength={8} pattern="[0-9]{8}" required value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,''))} placeholder="8 dígitos"/></label>{authError&&<p className="error" role="alert">{authError}</p>}<Button kind="primary" disabled={authBusy}>{authBusy?'Verificando…':'Entrar a la demo'}<ArrowRight size={17}/></Button><small><ShieldCheck size={14}/> Recordaremos el acceso en este navegador durante 30 días.</small></form></div></div>;
 const nav=role==='tutor'?[['dashboard','Inicio',LayoutDashboard],['students','Alumnos',Users],['library','Biblioteca',BookOpen],['classes','Clases',CalendarDays],['assessments','Evaluaciones',ClipboardCheck]]:[['dashboard','Inicio',LayoutDashboard],['path','Mi recorrido',Layers],['classes','Mis clases',CalendarDays],['practice','Práctica',Headphones],['feedback','Mi feedback',MessageSquare]];
 const pending=state.submissions.filter(s=>s.status==='pending').length;
 function patchItem(sid,id,fn){update(s=>{const it=s.plans[sid].items.find(x=>x.id===id);fn(it,s);});}
 const complete=(sid,id)=>{update(s=>{const p=s.plans[sid],i=p.items.findIndex(x=>x.id===id);p.items[i].status='completed';if(p.items[i+1]?.status==='locked')p.items[i+1].status='available';});notify('Módulo completado. El siguiente material ya está disponible.');};
 const ctx={state,update,go,notify,role,student:currentStudent,plan,moduleId,item,openModule,setDialog,complete,patchItem,budget,refreshBudget};
 return <div className="app-shell"><div className="demo-bar"><span className="demo-label"><span className="pulse"/> DEMO INTERACTIVA <span className="demo-date">/ 12 OCT 2026</span></span><div className="role-switch" aria-label="Simular perfil">{[['tutor','Profesora'],['lucia','Alumno · Lucía'],['tomas','Alumno · Tomás']].map(([r,l])=><button key={r} className={role===r?'selected':''} onClick={()=>switchRole(r)}>{r==='tutor'?<GraduationCap size={14}/>:<span className={`tiny-dot ${r}`}/>} {l}</button>)}</div><button className="demo-tool" onClick={()=>setDialog({type:'reset'})}><RotateCcw size={13}/> Reiniciar demo</button></div>
 <aside className="sidebar"><button className="brand" onClick={()=>go('dashboard')}><span className="logo">tuinterin<span>.</span></span><span className="brand-sub">ACADEMY</span></button><div className="workspace-pill"><span className="workspace-symbol"><GraduationCap size={19}/></span><div><strong>{role==='tutor'?'Espacio del profesor':'Mi espacio de aprendizaje'}</strong><span>Business English</span></div></div><span className="nav-label">{role==='tutor'?'ENSEÑAR':'APRENDER'}</span><nav>{nav.map(([v,l,C])=><button key={v} onClick={()=>go(v)} className={(view===v||(v==='students'&&['profile','plan','builder'].includes(view))||(v==='library'&&view==='module'&&role==='tutor')||(v==='path'&&view==='module'&&role!=='tutor'))?'active':''}><C size={19}/>{l}{v==='assessments'&&pending>0&&<span className="nav-count">{pending}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="presentation-card"><span className="eyebrow">PARA LA PRESENTACIÓN</span><strong>Una biblioteca.<br/>Cada camino es personal.</strong><button onClick={()=>{setGuide(!guide);go('concept');}}>Explorar la propuesta <ArrowUpRight size={14}/></button></div><button className={'discovery-link '+(view==='discovery'?'active':'')} onClick={()=>go('discovery')}><Globe size={18}/> Así nos encuentran <ArrowUpRight size={14}/></button><div className="sidebar-user"><Avatar id={role}/><div><strong>{role==='tutor'?'Rocío Hernández':students[role].name}</strong><span>{role==='tutor'?'English Tutor':students[role].profession}</span></div><button aria-label="Cerrar acceso" title="Cerrar acceso en este navegador" onClick={()=>setDialog({type:'logout'})}><LogOut size={16}/></button></div></div></aside>
 <div className="main-shell"><header className="topbar"><div className="breadcrumb">Academy <ChevronRight size={13}/> <strong>{view==='dashboard'?'Inicio':view==='module'?mod(moduleId).title:({students:'Alumnos',profile:students[currentStudent].name,library:'Biblioteca de contenido',builder:'Crear learning plan',plan:'Learning plan',classes:'Clases',assessments:'Evaluaciones',path:'Mi recorrido',practice:'Práctica',roleplay:'AI Roleplay',writing:'Writing Practice',feedback:'Mi feedback',discovery:'Descubrimiento',concept:'La propuesta'})[view]}</strong></div><div className="topbar-right"><span className="date-label">Lunes, 12 de octubre</span><Badge tone="outline">{role==='tutor'?'Vista profesora':'Vista alumno'}</Badge><Avatar id={role} size="small"/></div></header>
 <main key={view+'-'+role}>
 {view==='dashboard'&&(role==='tutor'?<TutorDashboard {...ctx}/>:<StudentDashboard {...ctx}/>)}
 {view==='students'&&<Students {...ctx}/>}
 {view==='profile'&&<Profile {...ctx}/>}
 {view==='library'&&<Library {...ctx}/>}
 {view==='builder'&&<Builder {...ctx}/>}
 {(view==='plan'||view==='path')&&<LearningPlan {...ctx}/>}
 {view==='classes'&&<Classes {...ctx}/>}
 {view==='assessments'&&<Assessments {...ctx}/>}
 {view==='module'&&<ModuleWorkspace {...ctx}/>}
 {view==='practice'&&<Practice {...ctx}/>}
 {view==='writing'&&<Writing {...ctx}/>}
 {view==='roleplay'&&<Roleplay {...ctx}/>}
 {view==='feedback'&&<Feedback {...ctx}/>}
 {view==='discovery'&&<Discovery {...ctx}/>}
 {view==='concept'&&<Concept {...ctx}/>}
 <footer className="page-footer"><span>tuinterin academy <span>·</span> Aprender para ir más lejos.</span><span>Maqueta funcional · Datos ficticios · Estado guardado en este navegador</span></footer>
 </main></div>
 {toast&&<div className="toast" role="status"><CheckCircle2 size={19}/>{toast}</div>}
 {dialog&&<div className="modal-backdrop" onClick={()=>setDialog(null)}><div className="modal" onClick={e=>e.stopPropagation()}><button className="modal-close" aria-label="Cerrar" onClick={()=>setDialog(null)}><X size={20}/></button>{dialog.type==='reset'?<><span className="eyebrow">ESTADOS DE PRESENTACIÓN</span><h2>Vuelve al punto de partida.</h2><p>Esto restablece los alumnos, planes, clases y evaluaciones de este navegador. El presupuesto de IA y el acceso se conservan.</p><div className="stack"><Button kind="primary" onClick={()=>{setState(initialState());setDialog(null);go('dashboard');notify('Demo reiniciada: Tomás todavía no tiene plan.');}}>Antes de asignar el plan <ArrowRight size={16}/></Button><Button onClick={()=>{setState(initialState(true));setDialog(null);go('dashboard');notify('Escenario de curso activo cargado.');}}>Con el plan de Tomás activo</Button></div></>:dialog.type==='logout'?<><h2>Cerrar el acceso</h2><p>Se eliminará la autorización de este navegador. El código volverá a pedirse al entrar.</p><Button kind="primary" onClick={async()=>{await fetch('/api/access/logout',{method:'POST'});localStorage.removeItem('tuinterin-demo-access');setAuth(false);setDialog(null);}}>Cerrar acceso</Button></>:dialog.type==='class'?<ClassEditor {...ctx} session={dialog.session} onClose={()=>setDialog(null)}/>:dialog.type==='review'?<Review {...ctx} submissionId={dialog.id} onClose={()=>setDialog(null)}/>:dialog.type==='transcript'?<><h2>Transcript del intento</h2><Badge>{dialog.attempt.mode==='simulated'?'Resultado ilustrativo':'Práctica con IA'}</Badge><div className="transcript">{dialog.attempt.transcript.map((t,i)=><div className={'message '+t.role} key={i}><small>{t.role==='user'?'Alumno':'Alex · AI partner'}</small><p>{t.text}</p></div>)}</div></>:null}</div></div>}
 </div>;
}

function Heading({eyebrow,title,description,children}){return <div className="page-heading"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1>{description&&<p>{description}</p>}</div>{children&&<div className="heading-actions">{children}</div>}</div>;}
function SectionTitle({title,meta,action}){return <div className="section-title"><h2>{title}{meta&&<span>{meta}</span>}</h2>{action}</div>;}
function TutorDashboard({state,go,setDialog}){
 const pending=state.submissions.filter(x=>x.status==='pending').length;
 return <><Heading eyebrow="TU ESPACIO PARA ENSEÑAR" title="Buen día, Rocío 👋" description="Todo listo para acompañar el próximo paso de tus alumnos."><Button onClick={()=>setDialog({type:'class'})}><Plus size={16}/> Programar clase</Button></Heading>
 <div className="hero"><div className="hero-copy"><Badge>TEACH WITH PURPOSE</Badge><h2>El contenido es compartido.<br/><em>El camino es personal.</em></h2><p>Explora la biblioteca y construye el recorrido<br/>que cada profesional necesita.</p><Button kind="mint" onClick={()=>go('library')}>Explorar biblioteca <ArrowUpRight size={17}/></Button></div><img src="/assets/academy-hero.webp" alt="Ilustración de un recorrido de aprendizaje con escalones, un libro y un globo"/><span className="hero-caption">BUSINESS ENGLISH · BUILT AROUND YOU</span></div>
 <div className="stats-grid">{[[Users,'02','Alumnos en tu espacio','1 activo · '+(state.plans.tomas?'2 planes asignados':'1 por comenzar')],[CalendarDays,String(state.classes.filter(c=>c.status==='scheduled').length).padStart(2,'0'),'Próximas clases','Tu próxima clase: miércoles 14'],[ClipboardCheck,String(pending).padStart(2,'0'),'Evaluaciones pendientes','Tu feedback hace la diferencia']].map(([C,n,l,m],i)=><button className="stat-card" key={l} onClick={()=>go(['students','classes','assessments'][i])}><div className="stat-top"><span className="stat-icon"><C size={19}/></span><ArrowUpRight size={16}/></div><strong>{n}</strong><h3>{l}</h3><p>{m}</p></button>)}</div>
 <div className="dashboard-columns"><section><SectionTitle title="Tus alumnos" meta="2" action={<button className="text-link" onClick={()=>go('students')}>Ver todos <ArrowRight size={14}/></button>}/><div className="panel students-panel">{Object.values(students).map(s=><StudentRow key={s.id} s={s} state={state} go={go}/>)}</div><div className="insight-strip"><span className="insight-icon"><Puzzle size={20}/></span><div><strong>Una misma biblioteca, distintos objetivos</strong><p>Lucía sigue un path completo. Tomás se prepara para su próxima entrevista.</p></div><button aria-label="Ver propuesta modular" onClick={()=>go('concept')}><ArrowUpRight size={20}/></button></div></section>
 <section><SectionTitle title="Lo que viene" action={<button className="text-link" onClick={()=>go('classes')}>Calendario <ArrowRight size={14}/></button>}/><div className="panel agenda-panel">{state.classes.filter(c=>c.status==='scheduled').slice(0,2).map(c=><button key={c.id} className="agenda-item" onClick={()=>setDialog({type:'class',session:c})}><div className="date-box"><strong>{c.date.slice(8)}</strong><span>OCT</span></div><div><strong>{students[c.student].name}</strong><p>{c.module} · {mod(c.module).title}</p><small><Clock size={12}/> {c.time} · {c.duration} min</small></div><ChevronRight size={16}/></button>)}</div>{!state.plans.tomas?<div className="action-card"><Badge tone="amber">PRÓXIMO PASO</Badge><h3>Tomás está listo para comenzar.</h3><p>Ayúdalo a preparar su entrevista con un recorrido a medida.</p><button className="text-link" onClick={()=>go('profile','tomas')}>Crear su learning plan <ArrowRight size={15}/></button></div>:<div className="action-card"><Badge>PLAN ACTIVO</Badge><h3>Un recorrido para Tomás.</h3><p>{state.plans.tomas.items.length} módulos seleccionados de la biblioteca compartida.</p><button className="text-link" onClick={()=>go('plan','tomas')}>Administrar recorrido <ArrowRight size={15}/></button></div>}</section></div></>;
}
function StudentRow({s,state,go}){const p=state.plans[s.id];return <button className="student-row" onClick={()=>go('profile',s.id)}><Avatar id={s.id}/><div className="student-row-info"><strong>{s.name}</strong><p>{s.profession}</p><small>{p?p.name+' · '+p.items.length+' módulos':'Objetivo: entrevista laboral'}</small></div><div className="student-row-status"><Badge tone={p?'':'amber'}>{p?'Plan activo':'Necesita un plan'}</Badge><span>{p?'Ver alumno':'Configurar recorrido'} <ChevronRight size={13}/></span></div></button>;}
function Students({state,go}){const [q,setQ]=useState('');return <><Heading eyebrow="ACOMPAÑAMIENTO PERSONAL" title="Cada alumno, su camino." description="Objetivos, progreso y próximos pasos en un solo lugar."/><div className="toolbar"><div className="search-input"><Search size={17}/><input aria-label="Buscar alumnos" placeholder="Buscar por nombre o profesión…" value={q} onChange={e=>setQ(e.target.value)}/></div><Badge tone="outline">2 alumnos · Rocío Hernández</Badge></div><div className="panel">{Object.values(students).filter(s=>(s.name+s.profession).toLowerCase().includes(q.toLowerCase())).map(s=><StudentRow s={s} state={state} go={go} key={s.id}/>)}</div></>;}
function Profile({student,state,go,update,notify}){const s=students[student],p=state.plans[student];const [level,setLevel]=useState(state.levels[student]||'B1');return <><button className="back-link" onClick={()=>go('students')}><ChevronLeft size={15}/> Alumnos</button><Heading eyebrow="STUDENT PROFILE" title={s.name} description={s.profession+' · '+s.country}>{p?<Button kind="primary" onClick={()=>go('plan')}>Administrar learning plan <ArrowRight size={16}/></Button>:<Button kind="primary" onClick={()=>go('builder')}>Crear learning plan <Plus size={16}/></Button>}</Heading><div className="profile-layout"><section className="panel profile-card"><Avatar id={student} size="large"/><h2>{s.name}</h2><p>{s.profession}</p><Badge tone={p?'':'amber'}>{p?'Plan activo':'Plan no asignado'}</Badge><dl><dt>Correo</dt><dd>{s.email}</dd><dt>País y zona horaria</dt><dd>{s.country}<br/>{s.zone}</dd><dt>Industria</dt><dd>{s.industry}</dd><dt>Experiencia</dt><dd>{s.experience}</dd></dl><button className="disabled-link" disabled><FileText size={16}/> CV · No disponible</button></section><div className="stack"><section className="panel padded"><span className="eyebrow">EL OBJETIVO</span><h2>{s.goal}</h2><p>{student==='tomas'?'Prioridad: presentar su experiencia, explicar responsabilidades y comunicar logros. Fecha objetivo: 2 de noviembre de 2026.':'Prioridad: participar en reuniones, explicar proyectos y colaborar con equipos distribuidos.'}</p><div className="mini-facts"><span><Briefcase size={16}/> {s.profession}</span><span><Clock size={16}/> {student==='tomas'?'3 semanas':'A su ritmo'}</span><span><Layers size={16}/> {s.approach}</span></div></section><section className="panel padded"><SectionTitle title="Placement & tutor validation"/><p>Diagnóstico asistido por IA · Ejemplo ilustrativo</p><div className="placement"><span className="level-circle">B1</span><div><strong>Intermediate</strong><p>Comprende situaciones laborales habituales. Necesita consolidar tiempos verbales y ampliar sus respuestas.</p></div></div><label className="inline-label">Nivel validado por profesora<select value={level} onChange={e=>setLevel(e.target.value)}>{['A2','B1','B2','C1'].map(l=><option key={l}>{l}</option>)}</select><Button onClick={()=>{update(d=>{d.levels[student]=level;});notify('Nivel '+level+' confirmado por la profesora.');}}><Check size={15}/> Confirmar nivel</Button></label>{state.levels[student]&&<p className="success">Validado por Rocío · {state.levels[student]}</p>}</section><section className="panel padded"><SectionTitle title="Plan académico"/>{p?<><h3>{p.name}</h3><p>{p.approach} · {p.items.length} módulos · Inicio: {date(p.start)}</p><Button onClick={()=>go('plan')}>Ver recorrido <ArrowRight size={16}/></Button></>:<><p>Todavía no tiene un recorrido asignado. Elige una secuencia estándar o combina módulos según su objetivo.</p><div className="button-row"><Button onClick={()=>go('builder')}>Asignar Learning Path</Button><Button kind="primary" onClick={()=>go('builder')}>Construir Goal-Oriented Plan <ArrowRight size={16}/></Button></div></>}</section></div></div></>;}

function Library({go,openModule}){const [tab,setTab]=useState('paths'),[q,setQ]=useState(''),[level,setLevel]=useState('B1'),[variant,setVariant]=useState('all'),[skill,setSkill]=useState('all');const filtered=modules.filter(m=>(m.title+m.objective).toLowerCase().includes(q.toLowerCase())&&(variant==='all'||(variant==='yes'?m.variants.length>0:m.variants.includes(variant)))&&(skill==='all'||m.tag===skill));return <><Heading eyebrow="CONTENT LIBRARY" title="Una biblioteca. Infinitas posibilidades." description="Módulos reutilizables, organizados por capacidad profesional. Elige el recorrido, suma contexto."/><div className="tabs"><button className={tab==='paths'?'active':''} onClick={()=>setTab('paths')}><Layers size={17}/> Learning Paths</button><button className={tab==='modules'?'active':''} onClick={()=>setTab('modules')}><BookOpen size={17}/> Todos los módulos <Badge tone="outline">10</Badge></button><button className={tab==='resources'?'active':''} onClick={()=>setTab('resources')}><FileText size={17}/> Materiales originales <Badge tone="outline">7</Badge></button></div>
 {tab==='paths'?<><div className="path-feature panel"><div className="path-feature-intro"><span className="path-art"><BookOpen size={48}/><span>B1</span></span><div><div className="button-row"><Badge>B1 · INTERMEDIATE</Badge><Badge tone="outline">Disponible en la demo</Badge></div><h2>General Business English</h2><p>Las capacidades que necesitas para desenvolverte<br/>con confianza en el trabajo.</p><small>8 módulos · Orden recomendado · Variantes opcionales</small></div><Button kind="primary" onClick={()=>setTab('modules')}>Explorar módulos <ArrowRight size={16}/></Button></div><div className="path-module-grid">{modules.filter(m=>!m.special).map(m=><button key={m.id} onClick={()=>openModule(m.id)}><span>{m.id}</span><strong>{m.title}</strong>{m.variants.length>0?<Puzzle size={15}/>:<ArrowUpRight size={14}/>}</button>)}</div></div><SectionTitle title="Más caminos por venir" meta="Vista de crecimiento"/><div className="three-grid">{[['B2','General Business English','Comunicación profesional de nivel intermedio alto.'],['B1–B2','Speaking Oriented','Confianza y fluidez en situaciones profesionales.'],['C1','Executive Communication','Comunicación estratégica y liderazgo.']].map(([l,t,d])=><div className="panel unavailable-card" key={t}><Badge tone="outline">{l}</Badge><h3>{t}</h3><p>{d}</p><Badge tone="muted"><Lock size={11}/> No disponible</Badge></div>)}</div></>:tab==='resources'?<Resources/>:<><div className="toolbar wrap"><div className="search-input"><Search size={17}/><input placeholder="Buscar una capacidad o un módulo…" aria-label="Buscar módulos" value={q} onChange={e=>setQ(e.target.value)}/></div><select aria-label="Nivel" value={level} onChange={e=>setLevel(e.target.value)}><option>B1</option><option>B2</option><option>C1</option></select><select aria-label="Capacidad" value={skill} onChange={e=>setSkill(e.target.value)}><option value="all">Todas las capacidades</option>{[...new Set(modules.map(m=>m.tag))].map(t=><option key={t}>{t}</option>)}</select><select aria-label="Variantes" value={variant} onChange={e=>setVariant(e.target.value)}><option value="all">Todas las variantes</option><option value="yes">Con extensión</option><option>IT</option><option>Sales</option></select></div>{level!=='B1'?<Empty title={'Contenido '+level+' · No disponible'}>Este nivel muestra cómo crecerá la biblioteca. Explora B1 para probar los módulos.</Empty>:<><p className="result-count">{filtered.length} módulos · Una misma unidad puede formar parte de varios recorridos.</p><div className="module-grid">{filtered.map(m=><button className="panel module-card" key={m.id} onClick={()=>openModule(m.id)}><div className="card-top"><Icon module={m}/><Badge tone="outline">B1 · {m.id}</Badge></div><span className="eyebrow">{m.tag}</span><h3>{m.title}</h3><p>{m.objective}</p><div className="card-bottom"><span>{m.variants.length?<><Puzzle size={13}/> {m.variants.join(' · ')}</>:m.special?'Módulo especializado':'Core compartido'}</span><ArrowUpRight size={18}/></div>{m.id==='M08'&&<small className="content-note">Contenido ilustrativo para la demo</small>}</button>)}</div>{filtered.length===0&&<Empty title="No hay módulos para estos filtros">Prueba otra capacidad o variante.</Empty>}</>}</>}
 </>;}
function Resources(){return <><div className="notice"><FileText size={18}/><p>Las 7 planificaciones reales se presentan como documentos consultables y descargables. La numeración original se conserva y se distingue de los módulos del path B1.</p></div><div className="resource-list">{['Professional Introductions','Meetings','Understanding Customer Needs','Discovery Calls','Presenting Solutions','Handling Objections','Follow-up & Next Steps'].map((t,i)=><div className="panel resource-row" key={t}><span className="pdf-icon">PDF</span><div><strong>{t}</strong><p>Lesson Plan {i+1} · Material original de Sales</p></div><a className="btn" href={'/resources/lesson-'+(i+1)+'.pdf'} target="_blank" rel="noreferrer">Abrir <ExternalLink size={14}/></a><a className="btn icon-only" aria-label={'Descargar '+t} href={'/resources/lesson-'+(i+1)+'.pdf'} download><Download size={16}/></a></div>)}</div></>;}

function Builder({student,state,update,go,notify}){
 const [step,setStep]=useState(1),[approach,setApproach]=useState('Goal-Oriented'),[items,setItems]=useState([{id:'M01',variant:'Sales'},{id:'M02',variant:'Core'},{id:'M08',variant:'Core'}]),[name,setName]=useState('Interview preparation'),[start,setStart]=useState('2026-10-12');
 const selectApproach=a=>{setApproach(a);if(a==='Standard Learning Path'){setItems(modules.filter(m=>!m.special).map(m=>({id:m.id,variant:'Core'})));setName('General Business English');}else{setItems([{id:'M01',variant:'Sales'},{id:'M02',variant:'Core'},{id:'M08',variant:'Core'}]);setName('Interview preparation');}};
 function move(i,d){setItems(old=>{const n=[...old];[n[i],n[i+d]]=[n[i+d],n[i]];return n;});}
 function assign(){if(!name.trim()||!items.length)return;update(s=>{s.plans[student]={name:name.trim(),approach,start,items:items.map((it,i)=>({...it,status:i===0?'available':'locked',sessions:0}))};});notify('Plan asignado. Cambia a la vista de '+students[student].first+' para verlo.');go('plan');}
 return <><button className="back-link" onClick={()=>go('profile')}><ChevronLeft size={15}/> {students[student].name}</button><Heading eyebrow="LEARNING PLAN BUILDER" title="Diseña su próximo paso." description={'Un recorrido para '+students[student].name+' · '+students[student].goal}/><div className="wizard-steps">{['Enfoque','Módulos y orden','Variantes','Revisar y activar'].map((t,i)=><button className={step===i+1?'active':step>i+1?'done':''} onClick={()=>{if(i+1<=step)setStep(i+1);}} key={t}><span>{step>i+1?<Check size={15}/>:i+1}</span>{t}</button>)}</div><div className="panel wizard-body">
 {step===1?<><span className="eyebrow">PASO 01 / 04</span><h2>¿Cómo quiere aprender?</h2><p>Ambos enfoques utilizan los mismos módulos de la biblioteca.</p><div className="two-grid">{[['Standard Learning Path','Un camino completo','La secuencia recomendada de General Business English B1. Ocho módulos, a su ritmo.'],['Goal-Oriented','Un objetivo concreto','Selecciona y ordena módulos para preparar una entrevista o resolver una necesidad profesional.']].map(([a,t,d])=><button className={'choice-card '+(approach===a?'selected':'')} key={a} onClick={()=>selectApproach(a)}><span className="choice-check">{approach===a&&<Check size={15}/>}</span><Layers size={26}/><Badge tone="outline">{a}</Badge><h3>{t}</h3><p>{d}</p></button>)}</div></>:step===2?<><span className="eyebrow">PASO 02 / 04</span><h2>Elige los módulos y su orden.</h2><p>La selección usa contenido existente; no crea copias del curso.</p><div className="builder-columns"><div className="selection-list">{modules.map(m=><label key={m.id} className={items.some(it=>it.id===m.id)?'selected':''}><input type="checkbox" checked={items.some(it=>it.id===m.id)} onChange={e=>setItems(old=>e.target.checked?[...old,{id:m.id,variant:'Core'}]:old.filter(it=>it.id!==m.id))}/><div><small>{m.id} · B1</small><strong>{m.title}</strong></div>{m.special&&<Badge tone="outline">Sales</Badge>}</label>)}</div><div className="order-list"><span className="eyebrow">SU RECORRIDO · {items.length} MÓDULOS</span>{items.map((it,i)=><div className="order-row" key={it.id}><span>{i+1}</span><strong>{mod(it.id).title}</strong><button disabled={i===0} aria-label={'Subir '+it.id} onClick={()=>move(i,-1)}><ArrowUp size={15}/></button><button disabled={i===items.length-1} aria-label={'Bajar '+it.id} onClick={()=>move(i,1)}><ArrowDown size={15}/></button></div>)}{!items.length&&<p>Selecciona al menos un módulo.</p>}</div></div></>:step===3?<><span className="eyebrow">PASO 03 / 04</span><h2>Suma contexto donde aporta valor.</h2><p>El Core se mantiene. La extensión agrega vocabulario y situaciones específicas.</p>{items.map((it,i)=><div className="variant-row" key={it.id}><Icon module={mod(it.id)}/><div><small>{it.id} · Shared Core</small><strong>{mod(it.id).title}</strong></div><select aria-label={'Variante '+it.id} value={it.variant} onChange={e=>setItems(old=>old.map((x,j)=>j===i?{...x,variant:e.target.value}:x))}><option>Core</option>{mod(it.id).variants.map(v=><option key={v}>{v}</option>)}</select></div>)}<div className="notice"><Puzzle size={18}/><p>La variante se elige por módulo, según la necesidad del alumno.</p></div></>:<><span className="eyebrow">PASO 04 / 04</span><h2>Listo para empezar.</h2><div className="two-grid"><label>Nombre del plan<input value={name} maxLength={80} onChange={e=>setName(e.target.value)}/></label><label>Fecha de inicio<input type="date" value={start} required onChange={e=>setStart(e.target.value)}/></label></div><div className="plan-summary"><Avatar id={student}/><div><h3>{students[student].name}</h3><p>{approach} · B1 · {items.length} módulos</p></div><Badge>Primer módulo disponible</Badge></div>{items.map((it,i)=><div className="review-module" key={it.id}><span className="step-num">{i+1}</span><strong>{it.id} · {mod(it.id).title}</strong><Badge tone="outline">{it.variant==='Core'?'Core':'Core + '+it.variant}</Badge><span className="muted">{i===0?'Se libera al activar':'Liberación por profesora'}</span></div>)}<div className="notice"><CheckCircle2 size={18}/><p>Al activar, el alumno verá este recorrido y podrá abrir el primer módulo. Los siguientes permanecen visibles y bloqueados.</p></div></>}
 <div className="wizard-footer"><Button disabled={step===1} onClick={()=>setStep(step-1)}><ChevronLeft size={15}/> Atrás</Button><span>Paso {step} de 4</span>{step<4?<Button kind="primary" disabled={!items.length} onClick={()=>setStep(step+1)}>Continuar <ArrowRight size={16}/></Button>:<Button kind="primary" disabled={!name.trim()||!start||!items.length} onClick={assign}>Asignar y activar plan <Check size={16}/></Button>}</div></div></>;
}

function LearningPlan({student,role,plan,state,openModule,go,complete,patchItem,update,notify,setDialog}){const [add,setAdd]=useState('');if(!plan)return <><Heading eyebrow="MY LEARNING PLAN" title="Tu próximo capítulo está por empezar."/><Empty title="Tu profesora está preparando tu recorrido" action={role==='tutor'?<Button kind="primary" onClick={()=>go('builder')}>Crear learning plan</Button>:null}>{role==='tutor'?'Selecciona módulos y variantes para este alumno.':'Rocío seleccionará los módulos que te ayudarán a alcanzar tu objetivo. Aquí aparecerán cuando el plan esté asignado.'}</Empty></>;
 const completed=plan.items.filter(i=>i.status==='completed').length,progress=Math.round(completed/plan.items.length*100);
 function move(i,d){update(s=>{const items=s.plans[student].items;if(['completed','progress'].includes(items[i].status)||['completed','progress'].includes(items[i+d].status))return;[items[i],items[i+d]]=[items[i+d],items[i]];});}
 return <><Heading eyebrow={role==='tutor'?'ACTIVE LEARNING PLAN':'TU RECORRIDO'} title={plan.name} description={students[student].name+' · '+plan.approach+' · B1'}>{role==='tutor'&&<Button onClick={()=>setDialog({type:'class'})}><Plus size={16}/> Programar clase</Button>}</Heading><div className="path-overview panel"><div><Badge>{plan.approach}</Badge><h2>{students[student].goal}</h2><p>Inicio: {date(plan.start)} · Profesora: Rocío Hernández</p></div><div className="progress-summary"><strong>{progress}<span>%</span></strong><p>{completed} de {plan.items.length} módulos completados</p><div className="progress-track"><span style={{width:progress+'%'}}/></div></div></div><div className="notice subtle"><Layers size={19}/><p>{role==='tutor'?'Una o más sesiones por módulo. Completar un módulo libera el siguiente; las prácticas no bloquean el avance.':'Tu profesora libera el contenido a medida que avanzan. Puedes seguir practicando en los módulos completados.'}</p></div>
 <div className="journey-list">{plan.items.map((it,i)=>{const m=mod(it.id),attempts=state.attempts.filter(a=>a.student===student&&a.module===it.id),writing=state.submissions.filter(a=>a.student===student&&a.module===it.id).at(-1);return <div className={'journey-card panel '+it.status} key={it.id}><div className="journey-rail"><span>{it.status==='completed'?<Check size={18}/>:it.status==='locked'?<Lock size={15}/>:String(i+1).padStart(2,'0')}</span></div><div className="journey-main"><div className="button-row"><span className="eyebrow">{it.id} · B1</span><Badge tone={it.status==='locked'?'muted':it.status==='progress'?'blue':''}>{statusLabels[it.status]}</Badge>{it.variant!=='Core'&&<Badge tone="outline"><Puzzle size={11}/> {it.variant} Extension</Badge>}</div><h3>{m.title}</h3><p>{m.objective}</p><div className="journey-meta"><span><FileText size={13}/> Material {it.status==='locked'?'por liberar':'disponible'}</span><span><CalendarDays size={13}/> {it.sessions} sesiones</span><span><Mic size={13}/> Roleplay: {attempts.length?Math.max(...attempts.map(a=>a.score))+'/10':'Sin intentar'}</span><span><Mail size={13}/> Writing: {writing?(writing.status==='pending'?'Por corregir':writing.score+'/10'):'Sin entregar'}</span></div>{role==='tutor'&&it.status!=='completed'&&it.status!=='progress'&&<div className="future-edit"><label>Contenido<select value={it.variant} onChange={e=>patchItem(student,it.id,x=>{x.variant=e.target.value;})}><option>Core</option>{m.variants.map(v=><option key={v}>{v}</option>)}</select></label>{i>0&&!['completed','progress'].includes(plan.items[i-1].status)&&<button aria-label={'Subir '+it.id} onClick={()=>move(i,-1)}><ArrowUp size={16}/></button>}{i<plan.items.length-1&&!['completed','progress'].includes(plan.items[i+1].status)&&<button aria-label={'Bajar '+it.id} onClick={()=>move(i,1)}><ArrowDown size={16}/></button>}</div>}</div><div className="journey-actions">{role==='tutor'?<><Button onClick={()=>openModule(it.id)}>Previsualizar <ArrowUpRight size={14}/></Button>{it.status==='locked'?<Button kind="primary" onClick={()=>{patchItem(student,it.id,x=>{x.status='available';});notify('Material liberado para '+students[student].first+'.');}}><Lock size={14}/> Liberar material</Button>:it.status!=='completed'?<Button kind="primary" onClick={()=>complete(student,it.id)}><Check size={14}/> Completar módulo</Button>:<span className="success"><CheckCircle2 size={15}/> Historial conservado</span>}</>:<Button kind={it.status==='locked'?'':'primary'} disabled={it.status==='locked'} onClick={()=>openModule(it.id)}>{it.status==='locked'?<><Lock size={14}/> Próximamente</>:<>{it.status==='completed'?'Repasar módulo':'Abrir módulo'} <ArrowRight size={14}/></>}</Button>}</div></div>;})}</div>
 {role==='tutor'&&<div className="panel padded"><SectionTitle title="Agregar un módulo futuro"/><div className="button-row"><select aria-label="Agregar módulo" value={add} onChange={e=>setAdd(e.target.value)}><option value="">Seleccionar de la biblioteca…</option>{modules.filter(m=>!plan.items.some(i=>i.id===m.id)).map(m=><option value={m.id} key={m.id}>{m.id} · {m.title}</option>)}</select><Button disabled={!add} onClick={()=>{update(s=>{s.plans[student].items.push({id:add,variant:'Core',status:'locked',sessions:0});});setAdd('');notify('Módulo agregado al final del recorrido.');}}><Plus size={15}/> Agregar al plan</Button></div></div>}
 <div className="academic-package"><Clock size={18}/><div><strong>Las clases acompañan el recorrido.</strong><p>Paquete de referencia: 4 horas · La cantidad de sesiones es independiente de los módulos completados. Compra y pagos: no disponibles.</p></div></div></>;
}

function StudentDashboard(ctx){const {student,state,plan,go,openModule}=ctx,s=students[student];if(!plan)return <><Heading eyebrow="TU ESPACIO PARA APRENDER" title={'¡Hola, '+s.first+'!'} description="Tu objetivo es el punto de partida. Estamos preparando tu camino."/><div className="hero"><div className="hero-copy"><Badge>YOUR NEXT CHAPTER</Badge><h2>Tu próxima oportunidad.<br/><em>Tu propio camino.</em></h2><p>{s.goal}</p></div><img src="/assets/academy-hero.webp" alt="Un camino de aprendizaje"/></div><Empty title="Rocío está preparando tu learning plan">Cuando tu profesora asigne el plan, aquí verás tus módulos, materiales y próximas actividades.</Empty></>;
 const current=plan.items.find(i=>i.status==='progress')||plan.items.find(i=>i.status==='available')||plan.items[0],m=mod(current.id),done=plan.items.filter(i=>i.status==='completed').length,next=state.classes.find(c=>c.student===student&&c.status==='scheduled');
 return <><Heading eyebrow="TU ESPACIO PARA APRENDER" title={'¡Qué bueno verte, '+s.first+'!'} description="Cada conversación te acerca a tu próxima oportunidad."/><div className="student-hero hero"><div className="hero-copy"><Badge>YOUR CURRENT MODULE · B1</Badge><span className="eyebrow">{m.id} / {String(plan.items.length).padStart(2,'0')}</span><h2>{m.title}</h2><p>{m.objective}</p><div className="button-row"><Button kind="mint" onClick={()=>openModule(m.id)}>Continuar aprendiendo <ArrowRight size={16}/></Button>{current.variant!=='Core'&&<span className="hero-variant"><Puzzle size={14}/> {current.variant} Extension</span>}</div></div><img src="/assets/academy-hero.webp" alt="Ilustración de aprendizaje profesional"/></div><div className="three-grid"><button className="panel student-stat" onClick={()=>go('path')}><Layers size={21}/><span>Tu recorrido</span><strong>{done} <small>/ {plan.items.length} módulos</small></strong><div className="progress-track"><span style={{width:done/plan.items.length*100+'%'}}/></div></button><button className="panel student-stat" onClick={()=>go('classes')}><CalendarDays size={21}/><span>Tu próxima clase</span><strong>{next?date(next.date):'Por programar'}</strong><p>{next?next.time+' · '+next.duration+' min · Rocío Hernández':'Tu profesora coordinará la próxima sesión.'}</p></button><button className="panel student-stat" onClick={()=>go('feedback')}><MessageSquare size={21}/><span>Tus prácticas</span><strong>{state.submissions.filter(w=>w.student===student&&w.status==='pending').length} <small>por revisar</small></strong><p>Consulta tus resultados y el feedback de Rocío.</p></button></div><div className="dashboard-columns"><section><SectionTitle title="Tu camino, paso a paso" action={<button className="text-link" onClick={()=>go('path')}>Ver recorrido <ArrowRight size={14}/></button>}/><div className="panel">{plan.items.slice(0,3).map((it,i)=><button className={'compact-module '+(it.status==='locked'?'locked':'')} key={it.id} disabled={it.status==='locked'} onClick={()=>openModule(it.id)}><span className="step-num">{it.status==='completed'?<Check size={15}/>:i+1}</span><div><strong>{mod(it.id).title}</strong><p>{it.id} · {statusLabels[it.status]}</p></div>{it.status==='locked'?<Lock size={16}/>:<ArrowRight size={17}/>}</button>)}</div></section><section><SectionTitle title="Un poco de práctica, mucho progreso"/><div className="practice-teaser"><span className="stat-icon"><Mic size={21}/></span><h3>Tu próxima conversación empieza aquí.</h3><p>Practica una presentación profesional en un entorno seguro, antes de hacerlo en el mundo real.</p><Button onClick={()=>go('practice')}>Explorar práctica <ArrowRight size={15}/></Button></div></section></div></>;
}

function ModuleWorkspace({moduleId,role,item,student,go,notify,patchItem}){
 const m=mod(moduleId),[mode,setMode]=useState('document'),[section,setSection]=useState('Overview'),[variant,setVariant]=useState(role==='tutor'?'Core':item?.variant||'Core'),[source,setSource]=useState(null),[page,setPage]=useState(0);
 useEffect(()=>{fetch('/source/materials.json').then(r=>r.json()).then(d=>{setSource(d);}).catch(()=>{});},[]);
 useEffect(()=>{if(role!=='tutor'&&item?.status==='available')patchItem(student,moduleId,x=>{x.status='progress';});},[]);
 const sourceNo=m.resource,paragraphs=source?.['Business English for Sales Lesson Plan '+sourceNo+'.docx']||[],chunks=[];
 for(let i=0;i<paragraphs.length;i+=20)chunks.push(paragraphs.slice(i,i+20));
 const canInteractive=moduleId==='M01';
 return <><button className="back-link" onClick={()=>go(role==='tutor'?'library':'path')}><ChevronLeft size={15}/> {role==='tutor'?'Biblioteca':'Mi recorrido'}</button><Heading eyebrow={'B1 · '+m.id+' · '+(role==='tutor'?'TUTOR PREVIEW':'LEARNING WORKSPACE')} title={m.title} description={m.objective}/>
 <div className="workspace-controls"><div className="segmented"><button className={mode==='document'?'active':''} onClick={()=>setMode('document')}><FileText size={15}/> Material PDF</button><button disabled={!canInteractive} className={mode==='interactive'?'active':''} onClick={()=>setMode('interactive')}><Sparkles size={15}/> {canInteractive?'Probar contenido interactivo':'Interactivo · No disponible'}</button></div>{role==='tutor'?<div className="variant-switch"><span>Previsualizar</span>{['Core',...m.variants].map(v=><button className={variant===v?'active':''} key={v} onClick={()=>setVariant(v)}>{v==='Core'?'Core':'Core + '+v}</button>)}</div>:variant!=='Core'&&<Badge><Puzzle size={12}/> {variant} Extension</Badge>}</div>
 {moduleId==='M02'&&<div className="notice subtle"><FileText size={17}/><p>Recurso adaptado: la sección de responsabilidades de Lesson Plan 1 apoya este módulo. Las preguntas específicas de M02 son una propuesta de demo.</p></div>}
 {mode==='document'?<div className="document-layout"><div className="pdf-viewer"><div className="pdf-toolbar"><span><FileText size={15}/> {m.title}.pdf</span><div><button aria-label="Página anterior" disabled={page===0} onClick={()=>setPage(page-1)}><ChevronLeft size={16}/></button><span>{page+1} / {chunks.length||1}</span><button aria-label="Página siguiente" disabled={page>=chunks.length-1} onClick={()=>setPage(page+1)}><ChevronRight size={16}/></button><span className="pdf-zoom">100%</span>{sourceNo&&<a title="Descargar PDF" href={'/resources/lesson-'+sourceNo+'.pdf'} download><Download size={16}/></a>}</div></div><div className="pdf-canvas"><article className="paper"><div className="paper-brand"><strong>tuinterin<span>.</span></strong><span>BUSINESS ENGLISH / B1</span></div><div className="paper-kicker">{m.id} · LEARNING MATERIAL</div><h2>{m.title}</h2><p className="paper-lead">{m.objective}</p><div className="paper-rule"/>{sourceNo?<><div className="paper-source">Sales source · Lesson Plan {sourceNo} · {page===0?'Material real presentado en un visor simulado':'Continuación del material original'}</div>{!source?<p>Cargando material…</p>:(chunks[page]||[]).map((p,i)=>/^(\d+\.|[A-E]\. |Main objective:|Lesson Goal|Focus:|Level:|Duration:)/.test(p)||p.length<48?<h4 key={i}>{p}</h4>:<p key={i}>{p}</p>)}</>:<><Badge tone="amber">Contenido ilustrativo de la demo</Badge><h3>Warm-up · Tell me about yourself</h3><p>What attracted you to this position? What are your main strengths? Tell me about a professional achievement.</p><h3>Language Toolkit</h3><p>In my current role, I am responsible for…<br/>One achievement I am proud of is…<br/>I would like to contribute by…</p><h3>Speaking with your tutor</h3><p>Prepare a two-minute introduction. Describe your experience, a concrete achievement and why you are interested in the role.</p></>}{variant!=='Core'&&<Extension variant={variant} moduleId={moduleId}/>}<div className="paper-footer"><span>Tuinterin Academy · Material para demostración</span><span>{page+1}</span></div></article></div></div><aside className="material-aside"><div className="panel padded"><span className="eyebrow">EL MATERIAL DE LA CLASE</span><h3>Todo en un lugar.</h3><p>Lee la planificación aquí o descarga el PDF para repasar a tu ritmo.</p>{sourceNo?<a className="btn full" href={'/resources/lesson-'+sourceNo+'.pdf'} download><Download size={15}/> Descargar PDF</a>:<Badge tone="muted">PDF original · No disponible</Badge>}</div>{canInteractive&&<div className="interactive-callout"><Sparkles size={23}/><h3>¿Y si el material cobrara vida?</h3><p>Explora la alternativa con contenido interactivo: vocabulario, ejercicios y práctica en la plataforma.</p><Button kind="primary" onClick={()=>setMode('interactive')}>Probar alternativa <ArrowRight size={16}/></Button><small>Comparación de formatos · M01</small></div>}<div className="panel padded"><span className="eyebrow">DESPUÉS DE CLASE</span><h3>De la teoría a la práctica.</h3><p>{m.scenario}</p><Button disabled={role==='tutor'} onClick={()=>go('roleplay')}><Mic size={15}/> AI Roleplay {role==='tutor'&&'· Vista alumno'}</Button><Button disabled={role==='tutor'} onClick={()=>go('writing')}><Mail size={15}/> Writing Practice</Button>{moduleId!=='M01'&&<small>Escenarios ilustrativos. Demo funcional en M01.</small>}</div></aside></div>:<div className="interactive-layout"><aside className="section-nav"><span className="eyebrow">DENTRO DEL MÓDULO</span>{sections.filter(s=>s!=='Professional Extension'||variant!=='Core').map((s,i)=><button key={s} className={section===s?'active':''} onClick={()=>setSection(s)}><span>{String(i+1).padStart(2,'0')}</span>{s==='Professional Extension'?variant+' Extension':s}</button>)}<div className="section-nav-foot"><Badge tone="outline">Alternativa on-platform</Badge><p>Un ejemplo para decidir juntos cómo bajar el contenido.</p></div></aside><section className="panel interactive-content"><span className="eyebrow">{m.id} · SHARED CORE</span><h2>{section==='Professional Extension'?variant+' Extension':section}</h2>{section==='Overview'?<><p className="lead">Your professional story starts here.</p><p>By the end of this module, you will be able to introduce yourself professionally, describe your role and responsibilities, and talk about your experience.</p><div className="outcome-grid">{['Introduce yourself with confidence','Describe your role and responsibilities','Use present, past and present perfect','Ask about another person’s background'].map((t,i)=><div key={t}><span>0{i+1}</span><strong>{t}</strong></div>)}</div><div className="notice"><Clock size={17}/><p>Una o más clases con tu profesora, más práctica opcional a tu ritmo.</p></div><Button kind="primary" onClick={()=>setSection('Warm-up')}>Let’s begin <ArrowRight size={16}/></Button></>:section==='Warm-up'?<><p>Think about your own professional profile. Discuss these questions with your tutor.</p>{['What do you do?','What are your main responsibilities?','How long have you worked in your current position?','What did you do before your current job?','What do you enjoy most about your work?'].map((q,i)=><div className="warmup-question" key={q}><span>0{i+1}</span>{q}</div>)}<Badge tone="outline">Adaptado del Lesson Plan 1 real</Badge></>:section==='Input & examples'?<><p className="lead">Meeting a new professional contact</p><p>Alex is a project coordinator at an international company. Alex works with several teams and is responsible for organizing project timelines.</p><div className="dialogue"><p><strong>Alex</strong> Hi, I’m Alex. It’s nice to meet you.</p><p><strong>Jordan</strong> Nice to meet you too. What do you do?</p><p><strong>Alex</strong> I’m a project coordinator. I work closely with our teams to keep projects on track.</p><p><strong>Jordan</strong> How long have you worked there?</p><p><strong>Alex</strong> I’ve been here for three years. Before that, I worked in operations.</p></div><p>What does Alex do? Which sentence describes a finished past experience?</p><Badge tone="outline">Core general adaptado para la demo</Badge>{variant!=='Core'&&<Extension variant={variant} moduleId={moduleId}/>}</>:section==='Language Toolkit'?<><p>Choose the language that helps you tell your own professional story.</p>{[['Present Simple','Current responsibilities','I manage a team of five people.'],['Past Simple','Finished past experience','I worked for a logistics company for three years.'],['Present Perfect','Experience connected to the present','I have worked in international business for eight years.']].map(([t,d,e])=><div className="toolkit-block" key={t}><Badge>{t}</Badge><h3>{d}</h3><blockquote>{e}</blockquote></div>)}<div className="vocab-chips">{['role','responsibilities','coordinate','specialize in','be responsible for','experience','background','currently'].map(w=><span key={w}>{w}</span>)}</div>{variant!=='Core'&&<Extension variant={variant} moduleId={moduleId}/>}</>:section==='Guided Practice'?<Exercises/>:section==='Speaking Practice'?<><p className="lead">Professional Networking Simulation</p><p>You are attending a networking event. Introduce yourself, explain your role, describe your responsibilities, mention your experience and ask your tutor about their work.</p><div className="notice"><Users size={19}/><p>Actividad para trabajar con la profesora. Pueden repetirla con otro contexto y aplicar el feedback.</p></div><textarea rows={5} placeholder="Write a few notes to prepare your introduction…" aria-label="Notas de speaking"/></>:section==='Professional Extension'?<Extension variant={variant} moduleId={moduleId}/>:<><p>Put your professional English into action. These activities are optional and remain available after you complete the module.</p><div className="two-grid"><div className="practice-option"><Mic size={26}/><h3>AI Roleplay</h3><p>{m.scenario}</p><Badge tone="outline">5 min · 1 intento + 3 reintentos</Badge><Button kind="primary" disabled={role==='tutor'} onClick={()=>go('roleplay')}>Practicar conversación <ArrowRight size={15}/></Button></div><div className="practice-option"><Mail size={26}/><h3>Writing Practice</h3><p>Introduce yourself to your new team.</p><Badge tone="outline">80–120 words · Tutor review</Badge><Button disabled={role==='tutor'} onClick={()=>go('writing')}>Abrir writing <ArrowRight size={15}/></Button></div></div>{role==='tutor'&&<p>Selecciona la vista de alumno para probar estas actividades.</p>}</>}</section></div>}
 </>;
}
function Extension({variant,moduleId}){return <div className="extension-block"><Badge><Puzzle size={12}/> {variant} EXTENSION · PROPOSED DEMO CONTENT</Badge><h3>{variant==='IT'?'Your role in a development team':'Meeting a new business contact'}</h3><p>{variant==='IT'?'I work as a software developer. I’m responsible for implementing new features and reviewing code. I work closely with the product team during each sprint. I have worked in web development for three years.':'Emma is an Account Manager at BrightTech. She manages international accounts and works closely with clients to understand their needs. Before joining BrightTech, she worked in marketing for four years.'}</p><div className="vocab-chips">{(variant==='IT'?['development','requirements','sprint','code review','deployment']:['accounts','prospects','pipeline','clients','targets']).map(w=><span key={w}>{w}</span>)}</div><p className="extension-prompt">{variant==='IT'?'Which projects have you contributed to? What are your responsibilities during a sprint?':'How do you manage your accounts? What experience do you have with international clients?'}</p><small>{variant==='Sales'&&moduleId==='M01'?'Basado en el caso de Emma del Lesson Plan 1.':'Extensión ilustrativa pendiente de validación pedagógica.'} El Core y su objetivo se conservan.</small></div>;}
function Exercises(){const [choice,setChoice]=useState(''),[fill,setFill]=useState(''),[match,setMatch]=useState({}),[checked,setChecked]=useState(false);const correct=choice==='have worked'&&fill.trim().toLowerCase()==='for'&&match.responsibilities==='duties'&&match.background==='experience';return <><p>Three ways to turn the same content into practice.</p><div className="exercise"><Badge tone="outline">01 · MULTIPLE CHOICE</Badge><h3>I ______ in software development for three years.</h3><div className="answer-options">{['worked','have worked','am working'].map(v=><label className={choice===v?'selected':''} key={v}><input type="radio" name="tense" value={v} checked={choice===v} onChange={()=>{setChoice(v);setChecked(false);}}/>{v}</label>)}</div>{checked&&<p className={choice==='have worked'?'success':'error'}>{choice==='have worked'?'Correct!':'Try “have worked”.'} Present perfect connects past experience to the present.</p>}</div><div className="exercise"><Badge tone="outline">02 · FILL IN THE BLANK</Badge><h3>I have worked here <input className="blank-input" aria-label="Palabra faltante" value={fill} onChange={e=>{setFill(e.target.value);setChecked(false);}}/> three years.</h3>{checked&&<p className={fill.trim().toLowerCase()==='for'?'success':'error'}>Use “for” with a duration; use “since” with a starting point.</p>}</div><div className="exercise"><Badge tone="outline">03 · MATCHING</Badge><h3>Match the professional vocabulary.</h3>{[['responsibilities','duties'],['background','experience']].map(([v,c])=><label className="match-row" key={v}>{v}<select aria-label={'Meaning of '+v} value={match[v]||''} onChange={e=>{setMatch({...match,[v]:e.target.value});setChecked(false);}}><option value="">Choose the meaning…</option><option value="experience">Previous professional experience</option><option value="duties">The duties of your role</option></select>{checked&&(match[v]===c?<Check size={17}/>:<X size={17}/>)}</label>)}</div><Button kind="primary" onClick={()=>setChecked(true)}>Check answers <Check size={16}/></Button>{checked&&correct&&<div className="notice"><CheckCircle2 size={19}/><p>Well done! All three exercises are correct.</p></div>}</>;}

function Classes(ctx){const {role,state,student,setDialog}=ctx;const list=state.classes.filter(c=>role==='tutor'||c.student===student).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return <><Heading eyebrow={role==='tutor'?'CLASS MANAGEMENT':'TUS ENCUENTROS CON ROCÍO'} title={role==='tutor'?'El aprendizaje sucede juntos.':'Un espacio para ponerlo en práctica.'} description="Cada sesión se conecta con un alumno, un módulo y un próximo paso.">{role==='tutor'&&<Button kind="primary" onClick={()=>setDialog({type:'class'})}><Plus size={16}/> Programar clase</Button>}</Heading><div className="calendar-strip"><div><span>OCTUBRE</span><strong>2026</strong></div>{['Lun 12','Mar 13','Mié 14','Jue 15','Vie 16','Sáb 17','Dom 18'].map(d=><span key={d} className={list.some(c=>c.date==='2026-10-'+d.split(' ')[1])?'has-class':''}>{d.split(' ')[0]}<strong>{d.split(' ')[1]}</strong>{list.some(c=>c.date==='2026-10-'+d.split(' ')[1])&&<i/>}</span>)}</div><SectionTitle title="Agenda" meta={role==='tutor'?'Todos los alumnos':students[student].first}/><div className="stack">{list.map(c=><div key={c.id} className="panel class-card"><div className="date-box"><strong>{c.date.slice(8)}</strong><span>{new Date(c.date+'T12:00:00').toLocaleDateString('es',{month:'short'}).toUpperCase()}</span></div><div className="class-main"><div className="button-row"><h3>{role==='tutor'?students[c.student].name:mod(c.module).title}</h3><Badge tone={c.status==='completed'?'':'blue'}>{c.status==='completed'?'Realizada':'Programada'}</Badge></div><p>{c.module} · {mod(c.module).title}</p><small><Clock size={13}/> {c.time} · {c.duration} min · Buenos Aires (UTC−3) · Rocío Hernández</small></div><div className="class-actions">{role==='tutor'?<Button onClick={()=>setDialog({type:'class',session:c})}>Preparar / registrar clase <ArrowUpRight size={15}/></Button>:c.link?<a className="btn primary" target="_blank" rel="noreferrer" href={c.link}>Entrar a la videollamada <ExternalLink size={15}/></a>:<Badge tone="muted">Enlace por confirmar</Badge>}</div></div>)}</div><div className="notice subtle"><CalendarDays size={19}/><p>Las fechas de esta maqueta son ilustrativas. Un módulo puede necesitar varias clases: el progreso lo confirma la profesora.</p></div></>;}
function ClassEditor({session,student,state,update,onClose,notify,complete}){const [c,setC]=useState(session?structuredClone(session):{student,module:state.plans[student]?.items[0]?.id||'M01',date:'2026-10-16',time:'16:00',duration:60,link:'',notes:'',status:'scheduled',sections:[]}),[tab,setTab]=useState('before'),[finish,setFinish]=useState(false);const set=(k,v)=>setC({...c,[k]:v});function save(e){e.preventDefault();if(c.link&&!/^https:\/\//.test(c.link)){notify('Usa un enlace de videollamada que comience con https://.');return;}update(s=>{if(session){const i=s.classes.findIndex(x=>x.id===session.id);const firstCompletion=s.classes[i].status!=='completed'&&c.status==='completed';s.classes[i]={...c};if(firstCompletion){const it=s.plans[c.student]?.items.find(x=>x.id===c.module);if(it)it.sessions++;}}else{s.classes.push({...c,id:crypto.randomUUID()});} });if(finish&&c.status==='completed')complete(c.student,c.module);notify('Clase guardada. El alumno puede verla en Mis clases.');onClose();}return <form onSubmit={save}><span className="eyebrow">{session?'CLASS WORKSPACE':'NUEVA SESIÓN'}</span><h2>{session?'Preparar, enseñar y registrar.':'Programar una clase'}</h2><div className="tabs small-tabs">{[['before','Antes'],['during','Durante'],['after','Después']].map(([t,l])=><button type="button" className={tab===t?'active':''} key={t} onClick={()=>setTab(t)}>{l}</button>)}</div>{tab==='before'?<><div className="two-grid"><label>Alumno<select value={c.student} disabled={!!session} onChange={e=>set('student',e.target.value)}>{Object.values(students).map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>Módulo<select value={c.module} onChange={e=>set('module',e.target.value)}>{(state.plans[c.student]?.items||[{id:'M01'}]).map(it=><option key={it.id} value={it.id}>{it.id} · {mod(it.id).title}</option>)}</select></label><label>Fecha<input type="date" required value={c.date} onChange={e=>set('date',e.target.value)}/></label><label>Hora · Buenos Aires<input type="time" required value={c.time} onChange={e=>set('time',e.target.value)}/></label><label>Duración<select value={c.duration} onChange={e=>set('duration',Number(e.target.value))}>{[30,45,60,90].map(n=><option key={n} value={n}>{n} minutos</option>)}</select></label><label>Enlace de videollamada<input type="url" value={c.link} placeholder="https://meet.google.com/…" onChange={e=>set('link',e.target.value)}/></label></div><div className="notice"><BookOpen size={18}/><p>{mod(c.module).objective}<br/>Contenido asignado: {state.plans[c.student]?.items.find(it=>it.id===c.module)?.variant||'Core'}</p></div><div className="class-evidence"><strong>Prácticas para preparar la sesión</strong><p>Roleplay: {state.attempts.filter(a=>a.student===c.student&&a.module===c.module).length} intentos · Writing: {state.submissions.filter(w=>w.student===c.student&&w.module===c.module&&w.status==='pending').length} entregas por revisar</p></div></>:tab==='during'?<><p>Marca las secciones trabajadas. El registro se conserva al guardar la clase.</p>{sections.map(t=><label className="checkbox-line" key={t}><input type="checkbox" checked={c.sections.includes(t)} onChange={e=>set('sections',e.target.checked?[...c.sections,t]:c.sections.filter(s=>s!==t))}/>{t}</label>)}<label>Observaciones privadas<textarea rows={4} value={c.notes} onChange={e=>set('notes',e.target.value)}/></label></>:<><label>Registro y notas privadas<textarea rows={5} value={c.notes} onChange={e=>set('notes',e.target.value)}/></label><label className="checkbox-line"><input type="checkbox" checked={c.status==='completed'} onChange={e=>set('status',e.target.checked?'completed':'scheduled')}/>Registrar clase como realizada</label>{state.plans[c.student]?.items.some(it=>it.id===c.module&&it.status!=='completed')&&<label className="checkbox-line"><input type="checkbox" checked={finish} onChange={e=>setFinish(e.target.checked)}/>Objetivo alcanzado: completar módulo y liberar el siguiente</label>}<p className="muted">Puedes registrar una clase sin completar el módulo. Las tareas opcionales no condicionan el desbloqueo.</p></>}<div className="modal-footer"><Button type="button" onClick={onClose}>Cancelar</Button><Button kind="primary">Guardar clase <Check size={16}/></Button></div></form>;}

function Assessments(ctx){const {state,setDialog}=ctx;const [tab,setTab]=useState('writing');return <><Heading eyebrow="ASSESSMENT CENTER" title="Tu feedback hace la diferencia." description="La IA acompaña la práctica oral. La profesora evalúa la escritura y guía el próximo paso."/><div className="tabs"><button className={tab==='writing'?'active':''} onClick={()=>setTab('writing')}><Mail size={16}/> Writing <Badge tone="outline">{state.submissions.filter(s=>s.status==='pending').length} pendientes</Badge></button><button className={tab==='roleplay'?'active':''} onClick={()=>setTab('roleplay')}><Mic size={16}/> AI Roleplay · Historial</button></div>{tab==='writing'?<div className="stack">{state.submissions.slice().reverse().map(w=><div className="panel assessment-row" key={w.id}><Avatar id={w.student}/><div><h3>{students[w.student].name}</h3><p>{w.module} · {mod(w.module).title}</p><small>{words(w.text)} palabras · Entregado el {date(w.date)}</small></div><Badge tone={w.status==='pending'?'amber':w.score>=7?'':'red'}>{w.status==='pending'?'Por revisar':w.score+'/10 · '+(w.score>=7?'Approved':'Needs improvement')}</Badge><Button kind={w.status==='pending'?'primary':''} onClick={()=>setDialog({type:'review',id:w.id})}>{w.status==='pending'?'Revisar entrega':'Ver evaluación'} <ArrowUpRight size={15}/></Button></div>)}</div>:<div className="stack">{state.attempts.map(a=><div className="panel assessment-row" key={a.id}><Avatar id={a.student}/><div><h3>{students[a.student].name}</h3><p>{a.module} · {mod(a.module).title}</p><small>{date(a.date)} · {a.mode==='simulated'?'Ejemplo ilustrativo':'IA real · Evaluación sobre transcript'}</small></div><Badge tone={a.score>=7?'':'red'}>{a.score}/10 · {a.score>=7?'Approved':'Needs improvement'}</Badge><Button onClick={()=>setDialog({type:'transcript',attempt:a})}>Ver transcript <MessageSquare size={15}/></Button></div>)}</div>}<div className="notice subtle"><ShieldCheck size={19}/><p>Escala propuesta: 1 a 10 · Aprobación: 7/10. La práctica es opcional y no bloquea el avance del módulo.</p></div></>;}
function Review({submissionId,state,update,onClose,notify}){const w=state.submissions.find(x=>x.id===submissionId);const [rubric,setRubric]=useState(w.rubric||[8,8,7,8]),[score,setScore]=useState(w.score||8),[feedback,setFeedback]=useState(w.feedback||'');return <><span className="eyebrow">TUTOR REVIEW · {w.module}</span><h2>{students[w.student].name}</h2><p>{mod(w.module).writing}</p><div className="submission-text">{w.text}</div><small>{words(w.text)} palabras · Versión final entregada</small><div className="rubric">{rubricLabels.map((l,i)=><label key={l}>{l}<input aria-label={l} type="number" min={1} max={10} value={rubric[i]} onChange={e=>setRubric(r=>r.map((v,j)=>j===i?Number(e.target.value):v))}/><span>/10</span></label>)}</div><label>Nota final de la profesora<input type="number" min={1} max={10} value={score} onChange={e=>setScore(Number(e.target.value))}/></label><label>Feedback para el alumno<textarea rows={3} placeholder="Una fortaleza y un próximo paso concreto…" value={feedback} onChange={e=>setFeedback(e.target.value)}/></label><div className="modal-footer"><Button onClick={onClose}>Cerrar</Button><Button kind="primary" disabled={!feedback.trim()||score<1||score>10||rubric.some(n=>n<1||n>10)} onClick={()=>{update(s=>{const it=s.submissions.find(x=>x.id===submissionId);Object.assign(it,{status:'reviewed',score,rubric,feedback,reviewDate:'2026-10-12'});});notify('Feedback devuelto. Ya está visible en la cuenta del alumno.');onClose();}}>Devolver evaluación <Send size={16}/></Button></div></>;}

function Practice({student,plan,go}){return <><Heading eyebrow="AFTER-CLASS PRACTICE" title="La confianza se practica." description="Dos formas de poner en acción lo que aprendes. A tu ritmo, con acompañamiento."/>{!plan?<Empty title="Tu práctica aparecerá con tu recorrido">Primero tu profesora debe asignarte un plan.</Empty>:<div className="stack">{plan.items.map(it=>{const m=mod(it.id),enabled=m.id==='M01'&&it.status!=='locked';return <div key={m.id} className="panel practice-module"><div className="practice-module-heading"><Icon module={m}/><div><span className="eyebrow">{m.id} · {it.variant==='Core'?'B1':it.variant+' Extension'}</span><h2>{m.title}</h2></div><Badge tone={enabled?'':'muted'}>{enabled?'Demo funcional':it.status==='locked'?'Material bloqueado':'Escenario ilustrativo · No disponible'}</Badge></div><div className="two-grid"><div className="practice-option"><Mic size={24}/><h3>{m.scenario}</h3><p>Conversación profesional · AI partner</p><small>5 min · 1 intento inicial + 3 reintentos</small><Button kind="primary" disabled={!enabled} onClick={()=>go('roleplay',m.id)}>Abrir roleplay <ArrowRight size={15}/></Button></div><div className="practice-option"><Mail size={24}/><h3>Writing Practice</h3><p>{m.writing}</p><small>80–120 palabras · Feedback de la profesora</small><Button disabled={!enabled} onClick={()=>go('writing',m.id)}>Abrir writing <ArrowRight size={15}/></Button></div></div></div>;})}</div>}</>;}
function Writing({moduleId,student,state,update,notify,go,budget,refreshBudget}){const m=mod(moduleId),[text,setText]=useState(state.drafts[student+moduleId]||''),[suggestion,setSuggestion]=useState(''),[busy,setBusy]=useState(false),[sim,setSim]=useState(!budget?.configured),[seconds,setSeconds]=useState(0);const latest=state.submissions.filter(w=>w.student===student&&w.module===moduleId).at(-1);const submitted=latest?.status==='pending';useEffect(()=>{const t=setInterval(()=>setSeconds(s=>s+1),1000);return ()=>clearInterval(t);},[]);function edit(value){setText(value);update(s=>{s.drafts[student+moduleId]=value;});}async function suggestions(){if(sim){setSuggestion('Ejemplo ilustrativo: considera añadir un logro concreto de tu experiencia. Revisa “responsible for + -ing”. ¿Estás usando present perfect para una experiencia que continúa hasta hoy? Tu texto permanece intacto.');return;}setBusy(true);try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'writing',text})});const d=await r.json();if(!r.ok)throw Error(d.error);setSuggestion(d.text);refreshBudget();}catch(e){notify(e.message);}finally{setBusy(false);}}if(moduleId!=='M01')return <Empty title="Writing · No disponible">Prueba la actividad funcional de M01 en Práctica.</Empty>;return <><button className="back-link" onClick={()=>go('practice')}><ChevronLeft size={15}/> Práctica</button><Heading eyebrow="M01 · WRITING PRACTICE" title="Introduce yourself to your new team." description="Un primer correo. Una oportunidad de conectar."/><div className="writing-layout"><section className="panel writing-editor"><div className="editor-top"><Badge tone={submitted?'amber':'outline'}>{submitted?'Entrega pendiente de revisión':'Borrador'}</Badge><span><Clock size={14}/> {Math.floor(seconds/60)}:{String(seconds%60).padStart(2,'0')} · Orientativo: 10 min</span></div><div className="writing-prompt"><strong>YOUR TASK</strong><p>{m.writing}</p><small>Suggested length: 80–120 words · Level B1</small></div><textarea aria-label="Tu writing" maxLength={4000} placeholder="Hi everyone,\nMy name is…" value={text} onChange={e=>edit(e.target.value)} disabled={submitted}/><div className="editor-footer"><span className={words(text)>=80&&words(text)<=120?'success':''}>{words(text)} palabras <span className="muted">/ 80–120 sugeridas</span></span><span><CheckCircle2 size={13}/> Guardado en este navegador</span></div><div className="writing-actions"><Button disabled={busy||!text.trim()||submitted} onClick={suggestions}><Sparkles size={16}/>{busy?'Pensando…':'Sugerencias de IA'}</Button><Button kind="primary" disabled={words(text)<10||submitted} onClick={()=>{update(s=>{s.submissions.push({id:crypto.randomUUID(),student,module:moduleId,text,status:'pending',date:'2026-10-12',rubric:[8,8,7,8],score:8,feedback:''});});notify('Writing entregado a Rocío. Cambia a profesora → Evaluaciones para corregirlo.');}}>Entregar a profesora <Send size={16}/></Button></div>{submitted&&<div className="notice"><Clock size={18}/><p>Tu versión final ya fue entregada. Rocío la verá en su centro de evaluaciones.</p></div>}</section><aside className="stack"><div className="panel padded"><span className="stat-icon"><Sparkles size={22}/></span><h3>Una ayuda para pensar.</h3><p>La IA hace sugerencias. Tú decides qué cambiar; tu profesora evalúa el texto final.</p><label className="checkbox-line"><input type="checkbox" checked={sim} onChange={e=>setSim(e.target.checked)}/>Usar sugerencias ilustrativas</label>{!sim&&<small>{budget?.configured?'IA real habilitada · Presupuesto global limitado':'Completa OpenAI y MongoDB para habilitar la IA real.'}</small>}</div>{suggestion&&<div className="suggestion-card"><Badge>{sim?'EJEMPLO ILUSTRATIVO':'AI SUGGESTIONS'}</Badge><h3>Antes de entregar…</h3><p>{suggestion}</p><small>Tu texto no se reemplaza automáticamente.</small></div>}<div className="panel padded"><h3>Before you send</h3>{['Did you describe your current role?','Did you mention your responsibilities?','Did you include previous experience?','Did you use a professional closing?'].map(t=><p className="checklist" key={t}><Check size={14}/>{t}</p>)}</div></aside></div></>;}

function Roleplay({moduleId,student,state,update,notify,go,budget,refreshBudget,setDialog}){
 const [phase,setPhase]=useState('ready'),[sim,setSim]=useState(true),[transcript,setTranscript]=useState([]),[showTranscript,setShowTranscript]=useState(false),[seconds,setSeconds]=useState(300),[busy,setBusy]=useState(false),[recording,setRecording]=useState(false),[session,setSession]=useState(null),[result,setResult]=useState(null);
 const capture=useRef(null),playback=useRef(null),mounted=useRef(true),secondsRef=useRef(300);
 const attempts=state.attempts.filter(a=>a.student===student&&a.module===moduleId),variant=state.plans[student]?.items.find(x=>x.id===moduleId)?.variant||'Core';
 const stopCapture=()=>{const c=capture.current;if(!c)return null;clearTimeout(c.timeout);c.stream.getTracks().forEach(t=>t.stop());c.processor.disconnect();c.source.disconnect();c.audio.close();capture.current=null;setRecording(false);return c;};
 useEffect(()=>{mounted.current=true;return ()=>{mounted.current=false;stopCapture();if(playback.current)playback.current.pause();};},[]);
 useEffect(()=>{if(phase!=='active')return;const t=setInterval(()=>setSeconds(v=>{secondsRef.current=v-1;return Math.max(0,v-1);}),1000);return ()=>clearInterval(t);},[phase]);
 useEffect(()=>{if(phase==='active'&&seconds===0&&!busy)finish();},[seconds,busy,phase]);
 async function api(body){const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();refreshBudget();if(!r.ok)throw Error(d.error);return d;}
 async function start(){setBusy(true);try{if(!sim){const d=await api({action:'start',student,variant});setSession(d.session);}setTranscript([{role:'assistant',text:'Hi, I’m Alex. It’s nice to meet you! What do you do?'}]);setSeconds(300);secondsRef.current=300;setResult(null);setPhase('active');}catch(e){notify(e.message);}finally{setBusy(false);}}
 function simulatedTurn(){const turn=Math.floor(transcript.length/2);const user=(variant==='Sales'?['I’m a Sales Executive. I manage international accounts and build relationships with clients.','I have worked in sales for five years. Before that, I worked in customer service.','I helped our team increase sales by 15%. What do you enjoy about your work?']:['I’m a software developer. I implement new features and review code with my team.','I have worked in web development for three years. Before that, I worked at a startup.','I helped launch a new customer platform. What kind of projects do you work on?'])[Math.min(turn,2)];const next=['How long have you worked in your field?','Could you tell me about a project or achievement you’re proud of?','That sounds interesting. I work with international teams too. Thank you for sharing your experience.'][Math.min(turn,2)];setTranscript(t=>[...t,{role:'user',text:user},{role:'assistant',text:next}]);setShowTranscript(true);}
 async function record(){if(recording){await sendRecording();return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true}});if(!mounted.current){stream.getTracks().forEach(t=>t.stop());return;}const audio=new AudioContext({sampleRate:24000});await audio.resume();const source=audio.createMediaStreamSource(stream),processor=audio.createScriptProcessor(4096,1,1);const c={stream,audio,source,processor,chunks:[],count:0};processor.onaudioprocess=e=>{const samples=e.inputBuffer.getChannelData(0);const remain=480000-c.count;if(remain<=0)return;const a=samples.slice(0,remain);c.chunks.push(a);c.count+=a.length;};source.connect(processor);processor.connect(audio.destination);capture.current=c;setRecording(true);c.timeout=setTimeout(()=>sendRecording(),19500);}catch{notify('No se pudo abrir el micrófono. Revisa el permiso del navegador o usa el ejemplo ilustrativo.');}}
 async function sendRecording(){const c=stopCapture();if(!c||c.count<2400)return;const pcm=new Int16Array(c.count);let off=0;for(const chunk of c.chunks){for(let i=0;i<chunk.length;i++)pcm[off++]=Math.max(-1,Math.min(1,chunk[i]))*32767;}const bytes=new Uint8Array(pcm.buffer);let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));setBusy(true);try{const d=await api({action:'voice',session,audio:btoa(binary)});if(!mounted.current)return;setTranscript(t=>[...t,{role:'user',text:d.input||'[Audio recibido; transcripción no disponible]'},{role:'assistant',text:d.text}]);if(d.audio){const data=Uint8Array.from(atob(d.audio),c=>c.charCodeAt(0));const blob=new Blob([data],{type:'audio/wav'});const url=URL.createObjectURL(blob);const a=new Audio(url);playback.current=a;a.onended=()=>URL.revokeObjectURL(url);a.play().catch(()=>notify('Activa el audio del navegador. El transcript está disponible.'));}}catch(e){notify(e.message);}finally{if(mounted.current)setBusy(false);}}
 async function finish(){stopCapture();if(playback.current)playback.current.pause();if(transcript.filter(t=>t.role==='user').length===0){notify('Completa al menos una respuesta antes de terminar.');if(secondsRef.current<=0)setPhase('ready');return;}setBusy(true);try{let d=sim?{score:8,rubric:[9,8,7,8],feedback:'You communicated your role and experience clearly. Add a specific example of a project and the result you achieved. Review present perfect when describing experience that continues today.'}:await api({action:'finish',session});const a={id:crypto.randomUUID(),student,module:moduleId,score:d.score,rubric:d.rubric,feedback:d.feedback,transcript:sim?transcript:d.transcript,date:'2026-10-12',mode:sim?'simulated':'live'};update(s=>{s.attempts.push(a);});setResult(a);setPhase('results');}catch(e){notify(e.message);setPhase('ready');}finally{setBusy(false);}}
 if(moduleId!=='M01')return <Empty title="Roleplay · No disponible">El escenario funcional de esta demo está en M01.</Empty>;
 return <><button className="back-link" onClick={()=>go('practice')}><ChevronLeft size={15}/> Práctica</button><Heading eyebrow="M01 · AI ROLEPLAY" title="Your next conversation starts here." description="Un entorno seguro para practicar antes de dar el próximo paso."/>
 {phase==='results'&&result?<div className="results-layout"><div className="panel result-score"><Badge tone={result.score>=7?'':'red'}>{result.score>=7?'Approved':'Needs improvement'}</Badge><strong>{result.score}<span>/10</span></strong><h2>{result.score>=7?'Great progress, '+students[student].first+'!':'Keep practicing, '+students[student].first+'!'}</h2><p>{result.feedback}</p><small>{result.mode==='simulated'?'Resultado ilustrativo predeterminado':'Evaluación de IA sobre el transcript. No evalúa pronunciación.'}</small><Button onClick={()=>setDialog({type:'transcript',attempt:result})}>Ver transcript <MessageSquare size={16}/></Button><Button kind="primary" disabled={attempts.length>=4} onClick={()=>setPhase('ready')}>Volver a practicar <RotateCcw size={15}/></Button></div><div className="panel padded"><SectionTitle title="Your feedback"/>{['Task achievement','Communication & clarity','Grammar & accuracy','Professional vocabulary'].map((t,i)=><div className="score-row" key={t}><div><span>{t}</span><strong>{result.rubric[i]}/10</strong></div><div className="progress-track"><span style={{width:result.rubric[i]*10+'%'}}/></div></div>)}<div className="notice"><Lightbulb size={19}/><p>Try expanding your answers: what did you contribute, and what happened as a result?</p></div></div></div>:phase==='ready'?<div className="roleplay-layout"><div className="roleplay-scene"><div className="scene-orbit"><Globe size={62}/><span className="orbit-bubble"><MessageSquare size={25}/></span><span className="orbit-bubble second"><Briefcase size={22}/></span></div><Badge>PROFESSIONAL INTRODUCTIONS · B1</Badge><h2>International<br/>Networking Event</h2><p>You’re attending a networking event in London. Meet an international professional and share your role and experience.</p><div className="scene-meta"><span><Clock size={16}/> 5 minutes</span><span><RotateCcw size={16}/> {Math.max(0,4-attempts.length)} intentos restantes</span></div></div><div className="panel padded roleplay-instructions"><span className="eyebrow">YOUR OBJECTIVES</span><h2>Make a connection.</h2>{['Introduce yourself professionally.','Explain your role and responsibilities.','Share your previous experience.','Ask Alex about their background.'].map(t=><p className="checklist" key={t}><CheckCircle2 size={17}/>{t}</p>)}{variant!=='Core'&&<Badge tone="outline">Contexto: {variant} Extension</Badge>}<div className="practice-mode"><label className="checkbox-line"><input type="checkbox" checked={sim} onChange={e=>setSim(e.target.checked)}/>Recorrer un ejemplo ilustrativo</label><small>{sim?'Sin micrófono ni consumo de IA. Transcript y resultado predeterminados.':'Voz IA real · Pulsa para grabar cada respuesta (máximo 20 s). Respuesta hablada con Realtime mini.'}</small></div><Button kind="primary full" disabled={busy||attempts.length>=4||(!sim&&!budget?.configured)} onClick={start}>{busy?'Preparando…':attempts.length>=4?'Intentos agotados':sim?'Iniciar ejemplo':'Iniciar conversación con IA'}<Play size={16}/></Button><small>1 intento inicial + 3 reintentos · Mejor nota conservada.</small>{!sim&&!budget?.configured&&<p className="error">{budget?.error||'IA real no disponible: revisa la configuración de OpenAI y MongoDB.'}</p>}</div></div>:<div className="panel conversation-panel"><div className="conversation-top"><Badge tone={sim?'amber':''}>{sim?'SIMULACIÓN ILUSTRATIVA':'AI VOICE · REALTIME MINI'}</Badge><span className={seconds<30?'error':''}><Clock size={16}/> {Math.floor(seconds/60)}:{String(seconds%60).padStart(2,'0')}</span></div><div className="ai-avatar">a<span>✦</span></div><h2>Alex</h2><p>Tu partner de conversación · Networking in London</p><div className={'voice-wave '+(recording||busy?'moving':'')}>{Array.from({length:25},(_,i)=><i key={i} style={{height:12+(Math.sin(i*1.7)+1)*15,animationDelay:i*40+'ms'}}/>)}</div><h3>{recording?'Te escucho… Pulsa para enviar.':busy?'Alex está preparando su respuesta…':transcript.at(-1)?.text}</h3><div className="button-row centered"><Button kind={recording?'danger':'primary'} disabled={busy||seconds===0} onClick={sim?simulatedTurn:record}>{sim?<Play size={17}/>:recording?<Square size={17}/>:<Mic size={17}/>} {sim?'Simular mi respuesta':recording?'Enviar respuesta':'Grabar mi respuesta'}</Button><Button disabled={busy} onClick={finish}>Terminar y ver feedback <Check size={16}/></Button></div><button className="text-link" onClick={()=>setShowTranscript(!showTranscript)}><MessageSquare size={15}/> {showTranscript?'Ocultar':'Mostrar'} transcript</button>{showTranscript&&<div className="transcript">{transcript.map((t,i)=><div key={i} className={'message '+t.role}><small>{t.role==='user'?students[student].first:'Alex · AI partner'}</small><p>{t.text}</p></div>)}</div>}</div>}
 {attempts.length>0&&<><SectionTitle title="Tu historial de práctica" meta={attempts.length+' de 4 intentos'}/><div className="panel">{attempts.map((a,i)=><button className="attempt-row" key={a.id} onClick={()=>setDialog({type:'transcript',attempt:a})}><span>Intento {i+1}</span><small>{a.mode==='simulated'?'Ilustrativo':'IA real'}</small><Badge tone={a.score>=7?'':'red'}>{a.score}/10</Badge><span>Ver transcript <ChevronRight size={13}/></span></button>)}</div></>}
 </>;
}

function Feedback({student,state,setDialog}){const reviews=state.submissions.filter(w=>w.student===student),attempts=state.attempts.filter(a=>a.student===student);return <><Heading eyebrow="MY FEEDBACK" title="Cada intento te enseña algo." description="Tus resultados, los comentarios de Rocío y tus próximos pasos."/><SectionTitle title="Writing · Feedback de tu profesora"/><div className="stack">{reviews.length?reviews.slice().reverse().map(w=><div key={w.id} className="panel padded feedback-card"><div className="button-row"><span className="eyebrow">{w.module} · {mod(w.module).title}</span><Badge tone={w.status==='pending'?'amber':w.score>=7?'':'red'}>{w.status==='pending'?'Pendiente de revisión':w.score+'/10 · '+(w.score>=7?'Approved':'Needs improvement')}</Badge></div><h3>Introduce yourself to your new team</h3>{w.status==='pending'?<p>Rocío recibió tu entrega. Su evaluación aparecerá aquí.</p>:<><blockquote>{w.feedback}</blockquote><div className="feedback-author"><Avatar id="tutor" size="small"/><span>Rocío Hernández · Tu profesora</span></div><div className="rubric-summary">{rubricLabels.map((l,i)=><div key={l}><span>{l}</span><strong>{w.rubric[i]}/10</strong></div>)}</div></>}</div>):<Empty title="Tu primera devolución está por llegar">Entrega un writing para recibir feedback de tu profesora.</Empty>}</div><SectionTitle title="AI Roleplay · Tus conversaciones"/><div className="stack">{attempts.map(a=><div className="panel padded feedback-card" key={a.id}><div className="button-row"><Badge>{a.score}/10 · {a.score>=7?'Approved':'Needs improvement'}</Badge><span className="muted">{a.module} · {date(a.date)} · {a.mode==='simulated'?'Resultado ilustrativo':'IA real'}</span></div><h3>{mod(a.module).scenario}</h3><p>{a.feedback}</p><Button onClick={()=>setDialog({type:'transcript',attempt:a})}>Ver transcript <MessageSquare size={15}/></Button></div>)}</div><div className="notice subtle"><GraduationCap size={18}/><p>Un módulo completado y sus prácticas son dimensiones distintas. Puedes avanzar con tu profesora y seguir practicando después.</p></div></>;}

function Discovery({go,role}){const [intent,setIntent]=useState('IT'),[stage,setStage]=useState('search');const copy={IT:{query:'inglés para programadores y equipos IT',title:'Inglés para IT. Tu talento, sin fronteras.',text:'Participa en stand-ups, explica tus proyectos y colabora con equipos globales.',examples:'Sprints · Code reviews · Technical updates'},Sales:{query:'business english para ventas internacionales',title:'El inglés que abre tu próxima conversación.',text:'Conecta con clientes, presenta soluciones y mueve oportunidades en inglés.',examples:'Networking · Discovery calls · Presentations'},General:{query:'business english clases para profesionales',title:'Tu carrera merece un inglés a la altura.',text:'Gana confianza para comunicarte en el trabajo y dar tu próximo paso profesional.',examples:'Meetings · Emails · Career opportunities'}}[intent];return <><Heading eyebrow="DEL DESCUBRIMIENTO AL APRENDIZAJE" title="Distintas búsquedas. Una misma academia." description="Así podemos comunicar la propuesta por profesión, manteniendo una biblioteca modular compartida."/><div className="intent-tabs">{['IT','Sales','General'].map(t=><button key={t} className={intent===t?'active':''} onClick={()=>{setIntent(t);setStage('search');}}>{t==='General'?'Business English':t==='IT'?'Business English for IT':'Business English for Sales'}</button>)}</div><Badge tone="amber">Simulación visual · Sin conexión con Google ni publicación SEO</Badge>{stage==='search'?<div className="search-simulation panel"><div className="google-word"><span>G</span><span>o</span><span>o</span><span>g</span><span>l</span><span>e</span></div><div className="fake-search"><Search size={19}/>{copy.query}<X size={17}/></div><div className="fake-search-tabs">Todo <span>Imágenes</span><span>Videos</span><span>Más</span></div><p className="result-count">Ejemplo conceptual de resultado orgánico</p><button className="search-result" onClick={()=>setStage('landing')}><div className="search-result-brand"><span className="search-favicon">t.</span><div><strong>Tuinterin Academy</strong><small>tuinterin.com › academy › {intent.toLowerCase()}</small></div></div><h2>{copy.title}</h2><p>{copy.text} Clases 1:1 con una profesora, material enfocado en tu trabajo y práctica con IA.</p><span>Abrir landing de ejemplo <ArrowUpRight size={14}/></span></button><div className="search-explanation"><Lightbulb size={21}/><p>La promesa comercial habla de su profesión.<br/>La experiencia académica se construye con Core + extensiones relevantes.</p></div></div>:<div className="landing-preview"><header><span className="logo">tuinterin<span>.</span></span><button onClick={()=>setStage('search')}><ChevronLeft size={14}/> Volver a la búsqueda</button><Badge tone="outline">Landing de ejemplo</Badge></header><div className="landing-hero"><div><span className="eyebrow">BUSINESS ENGLISH FOR {intent.toUpperCase()}</span><h2>{copy.title}</h2><p>{copy.text}</p><Button kind="mint" onClick={()=>go(role==='tutor'?'library':'path')}>Explorar la experiencia académica <ArrowRight size={16}/></Button><small>{copy.examples}</small></div><img src="/assets/academy-hero.webp" alt="Aprendizaje conectado con tu carrera"/></div><div className="three-grid"><div><Users size={26}/><h3>Tu profesora, contigo.</h3><p>Clases 1:1 enfocadas en tu objetivo.</p></div><div><Puzzle size={26}/><h3>Contenido con contexto.</h3><p>Un Core sólido. Extensiones cuando aportan valor.</p></div><div><Mic size={26}/><h3>Practica sin presión.</h3><p>Roleplay con IA y writing con feedback humano.</p></div></div></div>}<div className="discovery-flow">{['Búsqueda específica','Landing por profesión','Diagnóstico + tutor','Plan modular individual'].map((t,i)=><div key={t}><span>0{i+1}</span><strong>{t}</strong>{i<3&&<ArrowRight size={17}/>}</div>)}</div></>;}
function Concept({go,role,budget}){return <><Heading eyebrow="LA PROPUESTA DE PRODUCTO" title="Una biblioteca. Cada camino es personal." description="Cuatro capas conectadas para personalizar la experiencia sin duplicar contenido."/><div className="concept-layers">{[[BookOpen,'01','Biblioteca de contenido','Módulos independientes + extensiones opcionales. Un Core compartido que se mantiene.'],[Layers,'02','Recorridos de aprendizaje','Standard Path: M01 → M08. Goal-Oriented: selección y orden según un objetivo.'],[Users,'03','Plan individual del alumno','Tutor, nivel validado, variantes por módulo y progreso. Aquí vive la personalización.'],[CalendarDays,'04','Clases y práctica','Una o más sesiones por módulo. Material liberado, roleplay y writing con feedback.']].map(([C,n,t,d])=><div className="panel padded concept-layer" key={n}><span className="step-num">{n}</span><C size={27}/><h2>{t}</h2><p>{d}</p></div>)}</div><div className="two-grid"><div className="panel padded"><span className="eyebrow">GUION SUGERIDO · 6 MINUTOS</span><h2>La demo, paso a paso.</h2>{['Profesora → Tomás: revisar objetivo y confirmar nivel.','Crear plan: M01 + Sales, M02 Core, M08 Core.','Cambiar a Tomás y abrir su primer módulo.','Comparar PDF con la alternativa interactiva de M01.','Probar roleplay y entregar un writing.','Volver a profesora, corregir y liberar contenido.','Cambiar a alumno y comprobar el feedback.'].map((t,i)=><p className="guide-step" key={t}><span>{i+1}</span>{t}</p>)}<Button kind="primary" onClick={()=>go(role==='tutor'?'students':'path')}>Comenzar el recorrido <ArrowRight size={16}/></Button></div><div className="stack"><div className="panel padded"><span className="eyebrow">QUÉ ES FUNCIONAL</span><h3>Estados conectados, decisiones visibles.</h3><p>Roles, biblioteca, variantes, plan, clases, desbloqueos, ejercicios de M01, writing, evaluación y feedback.</p><Badge tone="outline">Persistencia local · Sin cuentas reales</Badge></div><div className="panel padded"><span className="eyebrow">IA DE LA DEMOSTRACIÓN</span><h3>Un presupuesto pequeño y controlado.</h3><p>{budget?.configured?'OpenAI y MongoDB configurados.':'La demo visual funciona sin servicios externos.'} Voz con Realtime mini, sugerencias con GPT-4.1 mini. También hay ejemplos ilustrativos sin consumo.</p><div className="budget-meter"><strong>US${((budget?.reservedMicro||0)/1e6).toFixed(2)} <span>/ US$1.00</span></strong><div className="progress-track"><span style={{width:Math.min(100,(budget?.reservedMicro||0)/10000)+'%'}}/></div><small>Presupuesto reservado conservador · No equivale a facturación exacta. No se restablece al reiniciar la demo.</small></div></div><div className="notice"><ShieldCheck size={18}/><p>No disponibles: pagos, videollamada integrada, B2/C1, autenticación individual y analíticas avanzadas.</p></div></div></div></>;}
